def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    max_opp_budget = 0.0
    pressure = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0.0) > max_opp_budget:
                max_opp_budget = opp.get('budget', 0.0)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 90:
                    pressure += 2
                elif bid >= 50:
                    pressure += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return min(budget, 18.0)

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    target = 0.0

    if prev_bids:
        highest_prev = max(prev_bids)
        moderate_prev = 0.0
        for b in prev_bids:
            if b <= 95 and b > moderate_prev:
                moderate_prev = b

        if urgency >= 4:
            if highest_prev >= 110:
                target = 92.0
            elif highest_prev >= 90:
                target = highest_prev + 2.0
            else:
                target = max(58.0, highest_prev + 2.5)
        elif scarcity >= 2:
            if moderate_prev > 0:
                target = max(42.0, moderate_prev + 1.5)
            else:
                target = 46.0
        elif scarcity >= 1:
            if highest_prev >= 95:
                target = 28.0
            else:
                target = max(24.0, highest_prev * 0.72)
        else:
            if highest_prev >= 100:
                target = 8.0
            elif highest_prev >= 80:
                target = 14.0
            else:
                target = max(12.0, highest_prev * 0.45)
    else:
        if urgency >= 4:
            target = 65.0
        elif scarcity >= 2:
            target = 40.0
        elif scarcity >= 1:
            target = 26.0
        else:
            target = 14.0

    if pressure >= 3 and urgency <= 2 and scarcity == 0:
        target *= 0.65
    elif pressure >= 3 and urgency >= 4:
        target = max(target, 78.0)

    reserve_floor = DAILY_SALARY * 2.2
    if budget < reserve_floor and urgency <= 2:
        target *= 0.8
    if budget < DAILY_SALARY and urgency <= 1:
        target *= 0.7

    if hp <= 2 or no_water >= 2:
        target = max(target, 88.0)

    if supply >= 23 and urgency <= 2:
        target *= 0.75

    if max_opp_budget > budget * 2 and urgency <= 2:
        target *= 0.85

    if target < 0:
        target = 0.0

    return float(min(budget, round(target, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from all alive opponents (immediate reaction)
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many full water units exist; use int indices safely
    # (not strictly needed, but keeps logic stable)
    units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0

    # Base aggressiveness: medium scenario tends to require contesting
    # Target band anchored to survivors' bids from yesterday.
    # If someone previously bid very high, we must respond.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_hp > 3.0 and my_no_water_days <= 0:
            desired = DAILY_SALARY * 0.32
        else:
            desired = DAILY_SALARY * 0.92
    else:
        # If bids were not extreme, slightly overbid the top to secure water.
        desired = max(DAILY_SALARY * 0.52, highest_prev_bid + 1.5)

    # If supply is tight (few units), increase bid.
    if units <= 1:
        desired *= 1.15

    # If our HP is critical, bid more.
    if my_hp <= 2.0:
        desired = max(desired, DAILY_SALARY * 0.9)

    # If we've already had no-water days, increase bid to break the streak.
    if my_no_water_days >= 1:
        desired = max(desired, DAILY_SALARY * 0.7)

    # Ensure we never exceed budget.
    bid = min(my_budget, desired)

    # If budget is tiny, still bid something nonzero only when needed.
    if bid <= 0.0:
        return 0.0
    return bid
